const uint32_t OG0TC1B_192x192_480fps_raw8_delay2_regs_count =
    sizeof(OG0TC1B_192x192_480fps_raw8_delay2_regs) / sizeof(OG0TC1B_192x192_480fps_raw8_delay2_regs[0]);

/* Wrapper function for i2c read
 *  read register value from OG Camera Sensor registers
 *   using i2c read API \ref camera_sensor_i2c_read
 *
 *  for OG Camera Sensor specific i2c configurations
 *   see \ref OG0TC1B_camera_sensor_i2c_cnfg
 */
#define OG0TC1B_READ_REG(reg_addr, reg_value, reg_size)                                             \
    camera_sensor_i2c_read(&OG0TC1B_camera_sensor_i2c_cnfg,                                         \
                           reg_addr,                                                               \
                           reg_value,                                                              \
                           (CAMERA_SENSOR_I2C_REG_SIZE) reg_size)

/* Wrapper function for i2c write
 *  write register value to OG Camera Sensor registers
 *   using i2c write API \ref camera_sensor_i2c_write.
 *
 *  for OG0TC1B Camera Sensor specific i2c configurations
 *   see \ref OG0TC1B_camera_sensor_i2c_cnfg
 */
#define OG0TC1B_WRITE_REG(reg_addr, reg_value, reg_size)                                            \
    camera_sensor_i2c_write(&OG0TC1B_camera_sensor_i2c_cnfg,                                        \
                            reg_addr,                                                              \
                            reg_value,                                                             \
                            (CAMERA_SENSOR_I2C_REG_SIZE) reg_size)

/* Supported I2C slave addresses for OG sensor modules */
#define OG0TC1B_CAMERA_SENSOR_SLAVE_ADDR 0x10

#define OG0TC1B_CHIP_ID_REGISTER_VALUE   0x5443

#define OG0TC1B_REG_CHIPID_H             0x300B
#define OG0TC1B_REG_CHIPID_L             0x300C

#define OG0TC1B_REG_MODE_SELECT          0x0100
#define OG0TC1B_MODE_STANDBY             0x00
#define OG0TC1B_MODE_STREAMING           0x01

/*Helper macro*/
#define ARRAY_SIZE(x)                   (sizeof(x) / sizeof((x)[0]))

/* ISP AE exposure registers (20-bit, stored in 1/16 row units) */
#define OG0TC1B_COARSE_INTEGRATION_TIME_H    0x3500
#define OG0TC1B_COARSE_INTEGRATION_TIME_M    0x3501
#define OG0TC1B_COARSE_INTEGRATION_TIME_L    0x3502
/* ISP AE gain registers */
#define OG0TC1B_GLOBAL_GAIN_H                0x3508
#define OG0TC1B_GLOBAL_GAIN_L                0x3509

/* Wrapper function for Delay
 * Delay for microsecond:
 * Provide busy loop delay
 */
#define OG0TC1B_DELAY_uSEC(usec) sys_busy_loop_us(usec)

/* OG Camera power GPIO port */
extern ARM_DRIVER_GPIO ARM_Driver_GPIO_(BOARD_CAMERA_POWER_GPIO_PORT);
static ARM_DRIVER_GPIO *GPIO_Driver_CAM_PWR = &ARM_Driver_GPIO_(BOARD_CAMERA_POWER_GPIO_PORT);

/* OG Camera reset GPIO port */
extern ARM_DRIVER_GPIO ARM_Driver_GPIO_(BOARD_CAMERA_RESET_GPIO_PORT);

#define OG0TC1B_STANDARD_RESET_PIN 0U

extern ARM_DRIVER_GPIO ARM_Driver_GPIO_(BOARD_CAMERA_I2C_C1_C2_GPIO_PORT);
ARM_DRIVER_GPIO *c1_c2_port = &ARM_Driver_GPIO_(BOARD_CAMERA_I2C_C1_C2_GPIO_PORT);

extern ARM_DRIVER_GPIO Driver_GPIO13;
extern ARM_DRIVER_GPIO Driver_GPIO14;

/* Camera triggers: C_TRIGGER_1 (P14_6) and C_TRIGGER_2 (P13_2) */
#define OG0TC1B_SELFIE_TRIGGER_PIN 6U
#define OG0TC1B_STANDARD_TRIGGER_PIN 2U

typedef enum {
    OG0TC1B_CAMERA_SELFIE = 0U,
    OG0TC1B_CAMERA_STANDARD = 1U,
    OG0TC1B_CAMERA_COUNT,
} OG0TC1B_CAMERA_ID;

typedef struct {
    uint32_t mux_value;
    ARM_DRIVER_GPIO *reset_driver;
    uint32_t reset_pin;
} OG0TC1B_CAMERA_CONFIG;

static const OG0TC1B_CAMERA_CONFIG OG0TC1B_camera_configs[OG0TC1B_CAMERA_COUNT] = {
    [OG0TC1B_CAMERA_SELFIE] = {
            .mux_value = 0U,
            .reset_driver = &ARM_Driver_GPIO_(BOARD_CAMERA_RESET_GPIO_PORT),
            .reset_pin = BOARD_CAMERA_RESET_GPIO_PIN,
        },
    [OG0TC1B_CAMERA_STANDARD] = {
            .mux_value = 1U,
            .reset_driver = &Driver_GPIO13,
            .reset_pin = OG0TC1B_STANDARD_RESET_PIN,
        },
};

/* I2C Driver Instance */
extern ARM_DRIVER_I2C ARM_Driver_I2C_(RTE_OG0TC1B_CAMERA_SENSOR_I2C_INSTANCE);

static CAMERA_SENSOR_SLAVE_I2C_CONFIG OG0TC1B_camera_sensor_i2c_cnfg = {
    .drv_i2c = &ARM_Driver_I2C_(RTE_OG0TC1B_CAMERA_SENSOR_I2C_INSTANCE),
    .bus_speed = ARM_I2C_BUS_SPEED_STANDARD,
    .cam_sensor_slave_addr = OG0TC1B_CAMERA_SENSOR_SLAVE_ADDR,
    .cam_sensor_slave_reg_addr_type = CAMERA_SENSOR_I2C_REG_ADDR_TYPE_16BIT,
};

static int32_t OG0TC1B_Select_Camera(OG0TC1B_CAMERA_ID camera)
{
    if (camera >= OG0TC1B_CAMERA_COUNT) {
        return ARM_DRIVER_ERROR_PARAMETER;
    }

    return c1_c2_port->SetValue(BOARD_CAMERA_I2C_C1_C2_GPIO_PIN, OG0TC1B_camera_configs[camera].mux_value);
}

static int32_t OG0TC1B_Read_Chip_Id(OG0TC1B_CAMERA_ID camera, uint16_t *chip_id)
{
    uint32_t value = 0;
    int32_t ret = OG0TC1B_Select_Camera(camera);
    if (ret != ARM_DRIVER_OK) {
        return ret;
    }

    ret = OG0TC1B_READ_REG(OG0TC1B_REG_CHIPID_H, &value, 1);
    if (ret != ARM_DRIVER_OK) {
        return ret;
    }
    *chip_id = (uint16_t)(value << 8);

    ret = OG0TC1B_READ_REG(OG0TC1B_REG_CHIPID_L, &value, 1);
    if (ret != ARM_DRIVER_OK) {
        return ret;
    }
    *chip_id |= (uint16_t)value;
    return (*chip_id == OG0TC1B_CHIP_ID_REGISTER_VALUE) ? ARM_DRIVER_OK : ARM_DRIVER_ERROR_UNSUPPORTED;
}

static int32_t OG0TC1B_Set_Reset(OG0TC1B_CAMERA_ID camera, uint32_t state)
{
    if (camera >= OG0TC1B_CAMERA_COUNT) {
        return ARM_DRIVER_ERROR_PARAMETER;
    }

    const OG0TC1B_CAMERA_CONFIG *config = &OG0TC1B_camera_configs[camera];
    return config->reset_driver->SetValue(config->reset_pin, state);
}

static int32_t OG0TC1B_Reset_Camera(OG0TC1B_CAMERA_ID camera)
{
    int32_t ret = OG0TC1B_Set_Reset(camera, GPIO_PIN_OUTPUT_STATE_LOW);
    if (ret != ARM_DRIVER_OK) {
        return ret;
    }

    OG0TC1B_DELAY_uSEC(5000);
    ret = OG0TC1B_Set_Reset(camera, GPIO_PIN_OUTPUT_STATE_HIGH);
    if (ret != ARM_DRIVER_OK) {
        return ret;
    }

    OG0TC1B_DELAY_uSEC(20000);
    return ARM_DRIVER_OK;
}

static int32_t OG0TC1B_Initialize_Output(ARM_DRIVER_GPIO *driver, uint32_t pin)
{
    int32_t ret = driver->Initialize(pin, NULL);
    if (ret != ARM_DRIVER_OK) {
        return ret;
    }
    ret = driver->PowerControl(pin, ARM_POWER_FULL);
    if (ret != ARM_DRIVER_OK) {
        return ret;
    }
    return driver->SetDirection(pin, GPIO_PIN_DIRECTION_OUTPUT);
}

#if (RTE_OG0TC1B_CAMERA_SENSOR_MANUAL_AE_CONTROL)
/**
 * @brief Set OG0TC1B exposure.
 * @param value : 20-bit value written as is to 0x3500-0x3502.
 */
static int32_t OG0TC1B_Camera_Exposure_Set(uint32_t value)
{
    int32_t ret;

    ret = OG0TC1B_WRITE_REG(OG0TC1B_COARSE_INTEGRATION_TIME_H, (value >> 16) & 0x0FU, 1);
    if (ret != ARM_DRIVER_OK) {
        return ret;
    }
    ret = OG0TC1B_WRITE_REG(OG0TC1B_COARSE_INTEGRATION_TIME_M, (value >> 8) & 0xFFU, 1);
    if (ret != ARM_DRIVER_OK) {
        return ret;
    }
    return OG0TC1B_WRITE_REG(OG0TC1B_COARSE_INTEGRATION_TIME_L, value & 0xFFU, 1);
}

/**
 * @brief Set OG0TC1B analog gain.
 * @param value : 16-bit value written as is to 0x3508-0x3509.
 */
static int32_t OG0TC1B_Camera_Gain_Set(uint32_t value)
{
    int32_t ret;

    ret = OG0TC1B_WRITE_REG(OG0TC1B_GLOBAL_GAIN_H, (value >> 8) & 0xFFU, 1);
    if (ret != ARM_DRIVER_OK) {
        return ret;
    }
    return OG0TC1B_WRITE_REG(OG0TC1B_GLOBAL_GAIN_L, value & 0xFFU, 1);
}

typedef int32_t (*OG0TC1B_SENSOR_UPDATE)(uint32_t value);

/* Applies an update to both sensors; returns the first error. */
static int32_t OG0TC1B_Update_Both(OG0TC1B_SENSOR_UPDATE update, uint32_t value)
{
    int32_t first_ret = ARM_DRIVER_OK;

    for (OG0TC1B_CAMERA_ID camera = OG0TC1B_CAMERA_SELFIE; camera < OG0TC1B_CAMERA_COUNT; ++camera) {
        int32_t ret = OG0TC1B_Select_Camera(camera);
        if (ret == ARM_DRIVER_OK) {
            ret = update(value);
        }
        if (first_ret == ARM_DRIVER_OK && ret != ARM_DRIVER_OK) {
            first_ret = ret;
        }
    }

    return first_ret;
}
#endif /* RTE_OG0TC1B_CAMERA_SENSOR_MANUAL_AE_CONTROL */

/**
 * @fn           void OG0TC1B_Sensor_Enable_Clk_Src(void)
 * @brief        Enable OGOTC1B Camera Sensor external clock source configuration.
 * @param[in]    none
 * @return       none
 */
static void OG0TC1B_Sensor_Enable_Clk_Src(void)
{
    set_cpi_pixel_clk(CPI_PIX_CLKSEL_AXI, RTE_OG0TC1B_CAMERA_SENSOR_MIPI_CSI_CLK_SCR_DIV);
}

/**
 * @fn           void OGOTC1B_Sensor_Disable_Clk_Src(void)
 * @brief        Disable OGOTC1B Camera Sensor external clock source configuration.
 * @param[in]    none
 * @return       none
 */
static void OG0TC1B_Sensor_Disable_Clk_Src(void) { clear_cpi_pixel_clk(); }

/**
 * @fn           int32_t OG0TC1B_Bulk_Write_Reg(const OG0TC1B_REG OG0TC1B_reg[],
 *                                     uint32_t total_num, uint32_t reg_size)
 * @brief        write array of registers value to OG Camera Sensor registers.
 * @param[in]    OG0TC1B_reg : OG Camera Sensor Register Array Structure
 * @param[in]    total_num   : total number of registers(size of array)
 * @param[in]    reg_size    : register size in bytes.
 * @return       \ref execution_status
 */
static int32_t OG0TC1B_Bulk_Write_Reg(const OG0TC1B_REG OG0TC1B_reg[], uint32_t total_num, uint32_t reg_size)
{
    uint32_t i = 0;
    int32_t ret = 0;

    for (i = 0; i < total_num; i++) {
        ret = OG0TC1B_WRITE_REG(OG0TC1B_reg[i].reg_addr, OG0TC1B_reg[i].reg_value, reg_size);
        if (ret != ARM_DRIVER_OK) {
            return ret;
        }
    }

    return ARM_DRIVER_OK;
}

/* One camera's register table, from og0tc1b_settings.c. */
typedef struct {
    const OG0TC1B_REG *regs;
    const uint32_t *count; /* the table's _count variable */
    /* Non-zero replaces the table's 0x38ba:0x38bb:0x38bc delay value; 0 keeps
     * the table's value. */
    uint32_t delay_override;
} OG0TC1B_PROFILE;

static int32_t OG0TC1B_Configure_Triggered_Sensor(OG0TC1B_CAMERA_ID camera, const OG0TC1B_PROFILE *profile)
{
    int32_t ret = OG0TC1B_Select_Camera(camera);
    if (ret != ARM_DRIVER_OK) {
        return ret;
    }

    ret = OG0TC1B_WRITE_REG(0x3665, 0x80, 1);
    if (ret != ARM_DRIVER_OK) {
        return ret;
    }
    ret = OG0TC1B_WRITE_REG(0x0103, 0x01, 1);
    if (ret != ARM_DRIVER_OK) {
        return ret;
    }
    OG0TC1B_DELAY_uSEC(100000);

    /* In the Triggered1StepReadout tables MODE_SELECT = streaming only arms the
     * sensor; it then sends one frame per FSIN pulse. Arm it after the delay
     * override below, so hold back the table's closing 0x0100 write. */
    uint32_t count = *profile->count;
    if ((count > 0U) && (profile->regs[count - 1U].reg_addr == OG0TC1B_REG_MODE_SELECT)) {
        count--;
    }
    ret = OG0TC1B_Bulk_Write_Reg(profile->regs, count, 1);
    if (ret != ARM_DRIVER_OK) {
        return ret;
    }
    if (profile->delay_override != 0U) {
        const OG0TC1B_REG delay_regs[] = {
            {0x38ba, (uint16_t)((profile->delay_override >> 16) & 0xFFU)},
            {0x38bb, (uint16_t)((profile->delay_override >> 8) & 0xFFU)},
            {0x38bc, (uint16_t)(profile->delay_override & 0xFFU)},
        };
        ret = OG0TC1B_Bulk_Write_Reg(delay_regs, ARRAY_SIZE(delay_regs), 1);
        if (ret != ARM_DRIVER_OK) {
            return ret;
        }
    }
    return OG0TC1B_WRITE_REG(OG0TC1B_REG_MODE_SELECT, OG0TC1B_MODE_STREAMING, 1);
}

/* Sensor setup for one frame size: CSI-2 data type and both cameras' tables.
 * The selfie camera (delay1) reads out first and the standard camera (delay2)
 * after it on the shared CSI-2 link; camera.c switches the D-PHY input to the
 * standard camera between the two frames. */
typedef struct {
    uint32_t dim; /* OG0TC1B_FRAME_DIM_*: square frame, dim x dim RAW8 in memory */
    uint8_t csi_data_type;
    OG0TC1B_PROFILE selfie;
    OG0TC1B_PROFILE standard;
} OG0TC1B_FRAME_MODE;

static const OG0TC1B_FRAME_MODE OG0TC1B_frame_modes[] = { {
        .dim = OG0TC1B_FRAME_DIM_400,
        .csi_data_type = OG0TC1B_CSI_DATA_TYPE_RAW10,
        .selfie = {OG0TC1B_400x400_120fps_raw10_delay1_regs, &OG0TC1B_400x400_120fps_raw10_delay1_regs_count, 0U},
        .standard = {OG0TC1B_400x400_120fps_raw10_delay2_regs, &OG0TC1B_400x400_120fps_raw10_delay2_regs_count, 0U},
    }, {
        /* The standard camera's delay is raised from the delay2 table's
         * 0x008200 to 0x0087DD: with the table value the standard frame was
         * lost in most capture sessions, as the D-PHY switch after the selfie
         * frame came too late. 0x0087DD has not failed. */
        .dim = OG0TC1B_FRAME_DIM_192,
        .csi_data_type = OG0TC1B_CSI_DATA_TYPE_RAW8,
        .selfie = {OG0TC1B_192x192_480fps_raw8_delay1_regs, &OG0TC1B_192x192_480fps_raw8_delay1_regs_count, 0U},
        .standard = {OG0TC1B_192x192_480fps_raw8_delay2_regs, &OG0TC1B_192x192_480fps_raw8_delay2_regs_count,
                     0x0087DDU},
    },
};

/* Mode applied by the next CPI_CAMERA_SENSOR_CONFIGURE; see
 * OG0TC1B_Select_Frame_Mode(). */
static const OG0TC1B_FRAME_MODE *OG0TC1B_frame_mode = &OG0TC1B_frame_modes[1];

/**
 * @fn           int32_t OG0TC1B_Camera_Hard_Reseten(void)
 * @brief        Hard Reset OG0TC1B Camera Sensor
 * @param[in]    none
 * @return       \ref execution_status
 */
static int32_t OG0TC1B_Camera_Hard_Reseten(void)
{
    int32_t ret = 0;
    for (OG0TC1B_CAMERA_ID camera = OG0TC1B_CAMERA_SELFIE; camera < OG0TC1B_CAMERA_COUNT; ++camera) {
        const OG0TC1B_CAMERA_CONFIG *config = &OG0TC1B_camera_configs[camera];
        ret = OG0TC1B_Initialize_Output(config->reset_driver, config->reset_pin);
        if (ret != ARM_DRIVER_OK) {
            return ret;
        }
    }

    ret = OG0TC1B_Initialize_Output(GPIO_Driver_CAM_PWR, BOARD_CAMERA_POWER_GPIO_PIN);
    if (ret != ARM_DRIVER_OK) {
        return ret;
    }

    /* Start from a defined state even on the first camera session, when
     * Uninit() has not yet asserted reset or removed sensor power. */
    ret = OG0TC1B_Set_Reset(OG0TC1B_CAMERA_SELFIE, GPIO_PIN_OUTPUT_STATE_LOW);
    if (ret != ARM_DRIVER_OK) {
        return ret;
    }

    ret = OG0TC1B_Set_Reset(OG0TC1B_CAMERA_STANDARD, GPIO_PIN_OUTPUT_STATE_LOW);
    if (ret != ARM_DRIVER_OK) {
        return ret;
    }

    ret = GPIO_Driver_CAM_PWR->SetValue(BOARD_CAMERA_POWER_GPIO_PIN, GPIO_PIN_OUTPUT_STATE_LOW);
    if (ret != ARM_DRIVER_OK) {
        return ret;
    }

    OG0TC1B_DELAY_uSEC(5000);

    ret = GPIO_Driver_CAM_PWR->SetValue(BOARD_CAMERA_POWER_GPIO_PIN, GPIO_PIN_OUTPUT_STATE_HIGH);
    if (ret != ARM_DRIVER_OK) {
        return ret;
    }

    OG0TC1B_DELAY_uSEC(5000);

    ret = OG0TC1B_Set_Reset(OG0TC1B_CAMERA_SELFIE, GPIO_PIN_OUTPUT_STATE_HIGH);
    if (ret != ARM_DRIVER_OK) {
        return ret;
    }

    ret = OG0TC1B_Set_Reset(OG0TC1B_CAMERA_STANDARD, GPIO_PIN_OUTPUT_STATE_HIGH);
    if (ret != ARM_DRIVER_OK) {
        return ret;
    }

    OG0TC1B_DELAY_uSEC(20000);

    return ARM_DRIVER_OK;
}

/* Identifies one sensor and leaves it in standby. */
static int32_t OG0TC1B_Init_Sensor_Once(OG0TC1B_CAMERA_ID camera)
{
    uint16_t chip_id = 0;
    int32_t ret = OG0TC1B_Read_Chip_Id(camera, &chip_id);
    if (ret != ARM_DRIVER_OK) {
        return ret;
    }

    return OG0TC1B_WRITE_REG(OG0TC1B_REG_MODE_SELECT, OG0TC1B_MODE_STANDBY, 1);
}

/* As OG0TC1B_Init_Sensor_Once(), with one sensor reset and retry if the sensor
 * does not answer. */
static int32_t OG0TC1B_Init_Sensor(OG0TC1B_CAMERA_ID camera)
{
    int32_t ret = OG0TC1B_Init_Sensor_Once(camera);
    if (ret == ARM_DRIVER_OK) {
        return ARM_DRIVER_OK;
    }

    ret = OG0TC1B_Reset_Camera(camera);
    if (ret != ARM_DRIVER_OK) {
        return ret;
    }

    return OG0TC1B_Init_Sensor_Once(camera);
}

static int32_t OG0TC1B_Init(void)
{
    int32_t ret = 0;

    // Initialize the C1_C2 pin to select the I2C1 MUX
    ret = OG0TC1B_Initialize_Output(c1_c2_port, BOARD_CAMERA_I2C_C1_C2_GPIO_PIN);
    if (ret != ARM_DRIVER_OK) {
        return ret;
    }

    ret = OG0TC1B_Initialize_Output(&Driver_GPIO14, OG0TC1B_SELFIE_TRIGGER_PIN);
    if (ret == ARM_DRIVER_OK) {
        ret = Driver_GPIO14.SetValue(OG0TC1B_SELFIE_TRIGGER_PIN, GPIO_PIN_OUTPUT_STATE_LOW);
    }
    if (ret != ARM_DRIVER_OK) {
        return ret;
    }
    ret = OG0TC1B_Initialize_Output(&Driver_GPIO13, OG0TC1B_STANDARD_TRIGGER_PIN);
    if (ret == ARM_DRIVER_OK) {
        ret = Driver_GPIO13.SetValue(OG0TC1B_STANDARD_TRIGGER_PIN, GPIO_PIN_OUTPUT_STATE_LOW);
    }
    if (ret != ARM_DRIVER_OK) {
        return ret;
    }

    // The XV clock seems being set to 400/20 = 20MHz.
    // The sensor takes 6~64MHz clock.
    OG0TC1B_Sensor_Enable_Clk_Src();

    // 5ms delay on PWR pin to reset the sensor.
    ret = OG0TC1B_Camera_Hard_Reseten();
    if (ret != ARM_DRIVER_OK) {
        return ret;
    }

    /* Initialize i2c using i3c driver instance depending on
     *  OG0TC1B Camera Sensor specific i2c configurations
     *   \ref OG0TC1B_camera_sensor_i2c_cnfg
     */
    ret = camera_sensor_i2c_init(&OG0TC1B_camera_sensor_i2c_cnfg);
    if (ret != ARM_DRIVER_OK) {
        return ret;
    }

    // Enable this to scan all i2c devices' address
    // uint16_t address = 0;
    // while(address <= 0x7F)
    // {
    //     printf("testing address 0x%02X\r\n",address);
    //     OG0TC1B_camera_sensor_i2c_cnfg.cam_sensor_slave_addr = address;
    //     ret = OG0TC1B_READ_REG(OG0TC1B_REG_CHIPID_H, &rcv_data, 1);
    //     if(ret == ARM_DRIVER_OK)
    //         printf("found I2C device at address 0x%02X\r\n", address);
    //     address++;
    // }
    // __BKPT(2);

    return OG0TC1B_Init_Sensor(OG0TC1B_CAMERA_SELFIE);

    /*OG0TC1B_Init_Sensor() call for standard camera will fail when only selfie camera is
      present and OG0TC1B_Init() returns before a frame can be captured.So the below code
      is commented out.*/

    /*if (ret != ARM_DRIVER_OK) {
        return ret;
    }
    return OG0TC1B_Init_Sensor(OG0TC1B_CAMERA_STANDARD);
    */
}

/* One FSIN pulse on both trigger pins: each armed sensor sends one frame. */
int32_t OG0TC1B_TriggerBoth(void)
{
    int32_t ret = Driver_GPIO14.SetValue(OG0TC1B_SELFIE_TRIGGER_PIN, GPIO_PIN_OUTPUT_STATE_HIGH);
    if (ret != ARM_DRIVER_OK) {
        return ret;
    }
    ret = Driver_GPIO13.SetValue(OG0TC1B_STANDARD_TRIGGER_PIN, GPIO_PIN_OUTPUT_STATE_HIGH);
    if (ret == ARM_DRIVER_OK) {
        OG0TC1B_DELAY_uSEC(1);
        ret = Driver_GPIO14.SetValue(OG0TC1B_SELFIE_TRIGGER_PIN, GPIO_PIN_OUTPUT_STATE_LOW);
    }
    int32_t standard_ret = Driver_GPIO13.SetValue(OG0TC1B_STANDARD_TRIGGER_PIN, GPIO_PIN_OUTPUT_STATE_LOW);
    return (ret == ARM_DRIVER_OK) ? standard_ret : ret;
}

/* Both sensors answer their chip-ID read. */
static int32_t OG0TC1B_CheckReachable(void)
{
    uint16_t chip_id = 0;
    int32_t ret = OG0TC1B_Read_Chip_Id(OG0TC1B_CAMERA_SELFIE, &chip_id);
    if (ret != ARM_DRIVER_OK) {
        return ret;
    }
    return OG0TC1B_Read_Chip_Id(OG0TC1B_CAMERA_STANDARD, &chip_id);
}

/* Puts both sensors in standby; returns the first error. */
static int32_t OG0TC1B_StopBoth(void)
{
    int32_t ret = OG0TC1B_Select_Camera(OG0TC1B_CAMERA_SELFIE);
    if (ret == ARM_DRIVER_OK) {
        ret = OG0TC1B_WRITE_REG(OG0TC1B_REG_MODE_SELECT, OG0TC1B_MODE_STANDBY, 1);
    }

    /* When standard camera is not present ,OG0TC1B_Stop reports an error.
     So the below code is commented out.*/

    /*int32_t mux_ret = OG0TC1B_Select_Camera(OG0TC1B_CAMERA_STANDARD);
    if (ret == ARM_DRIVER_OK) {
        ret = mux_ret;
    }
    if (mux_ret == ARM_DRIVER_OK) {
        int32_t standard_ret = OG0TC1B_WRITE_REG(OG0TC1B_REG_MODE_SELECT, OG0TC1B_MODE_STANDBY, 1);
        if (ret == ARM_DRIVER_OK) {
            ret = standard_ret;
        }
    }*/
    return ret;
}

/**
 * @fn           int32_t OG0TC1B_Start(void)
 * @brief        Start OG0TC1B Camera Sensor Streaming.
 * @param[in]    none
 * @return       \ref execution_status
 */
static int32_t OG0TC1B_Start(void) { return OG0TC1B_TriggerBoth(); }

/**
 * @fn           int32_t OG0TC1B_Stop(void)
 * @brief        Stop OG Camera Sensor Streaming.
 * @param[in]    none
 * @return       \ref execution_status
 */
int32_t OG0TC1B_Stop(void) { return OG0TC1B_StopBoth(); }

/**
 * @fn           int32_t OG0TC1B_Control(uint32_t control, uint32_t arg)
 * @brief        Control OG Camera Sensor.
 * @param[in]    control  : Operation
 * @param[in]    arg      : Argument of operation
 * @return       \ref execution_status
 */
static int32_t OG0TC1B_Control(uint32_t control, uint32_t arg)
{
    int32_t ret;

    ARG_UNUSED(arg);
    switch (control) {
    case CPI_CAMERA_SENSOR_CONFIGURE:
        /* Configures and arms both sensors for external trigger. */
        ret = OG0TC1B_Configure_Triggered_Sensor(OG0TC1B_CAMERA_SELFIE, &OG0TC1B_frame_mode->selfie);
        if (ret != ARM_DRIVER_OK) {
            return ret;
        }
        ret = OG0TC1B_Configure_Triggered_Sensor(OG0TC1B_CAMERA_STANDARD, &OG0TC1B_frame_mode->standard);
        if (ret != ARM_DRIVER_OK) {
            return ret;
        }
        return OG0TC1B_CheckReachable();

#if (RTE_OG0TC1B_CAMERA_SENSOR_MANUAL_AE_CONTROL)
    case CPI_ISP_CAMERA_SENSOR_EXPOSURE:
        return OG0TC1B_Update_Both(OG0TC1B_Camera_Exposure_Set, arg & 0xFFFFFU);

    case CPI_ISP_CAMERA_SENSOR_GAIN:
        return OG0TC1B_Update_Both(OG0TC1B_Camera_Gain_Set, arg & 0xFFFFU);
#endif
    default:
        return ARM_DRIVER_ERROR_PARAMETER;
    }
}

/**
 * @fn           int32_t OG0TC1B_Uninit(void)
 * @brief        Un-initialize OG0TC1B Camera Sensor.
 * @param[in]    none
 * @return       \ref execution_status
 */
static int32_t OG0TC1B_Uninit(void)
{
    int32_t first_ret = ARM_DRIVER_OK;

    /*Disable camera sensor clock source config*/
    OG0TC1B_Sensor_Disable_Clk_Src();

    for (OG0TC1B_CAMERA_ID camera = OG0TC1B_CAMERA_SELFIE; camera < OG0TC1B_CAMERA_COUNT; ++camera) {
        const OG0TC1B_CAMERA_CONFIG *config = &OG0TC1B_camera_configs[camera];
        int32_t ret = config->reset_driver->SetValue(config->reset_pin, GPIO_PIN_OUTPUT_STATE_LOW);
        if (first_ret == ARM_DRIVER_OK && ret != ARM_DRIVER_OK) {
            first_ret = ret;
        }
        ret = config->reset_driver->PowerControl(config->reset_pin, ARM_POWER_OFF);
        if (first_ret == ARM_DRIVER_OK && ret != ARM_DRIVER_OK) {
            first_ret = ret;
        }
        ret = config->reset_driver->Uninitialize(config->reset_pin);
        if (first_ret == ARM_DRIVER_OK && ret != ARM_DRIVER_OK) {
            first_ret = ret;
        }
    }

    int32_t ret = Driver_GPIO14.PowerControl(OG0TC1B_SELFIE_TRIGGER_PIN, ARM_POWER_OFF);
    if (first_ret == ARM_DRIVER_OK && ret != ARM_DRIVER_OK) {
        first_ret = ret;
    }
    ret = Driver_GPIO14.Uninitialize(OG0TC1B_SELFIE_TRIGGER_PIN);
    if (first_ret == ARM_DRIVER_OK && ret != ARM_DRIVER_OK) {
        first_ret = ret;
    }
    ret = Driver_GPIO13.PowerControl(OG0TC1B_STANDARD_TRIGGER_PIN, ARM_POWER_OFF);
    if (first_ret == ARM_DRIVER_OK && ret != ARM_DRIVER_OK) {
        first_ret = ret;
    }
    ret = Driver_GPIO13.Uninitialize(OG0TC1B_STANDARD_TRIGGER_PIN);
    if (first_ret == ARM_DRIVER_OK && ret != ARM_DRIVER_OK) {
        first_ret = ret;
    }

    ret = GPIO_Driver_CAM_PWR->SetValue(BOARD_CAMERA_POWER_GPIO_PIN, GPIO_PIN_OUTPUT_STATE_LOW);
    if (first_ret == ARM_DRIVER_OK && ret != ARM_DRIVER_OK) {
        first_ret = ret;
    }

    ret = GPIO_Driver_CAM_PWR->PowerControl(BOARD_CAMERA_POWER_GPIO_PIN, ARM_POWER_OFF);
    if (first_ret == ARM_DRIVER_OK && ret != ARM_DRIVER_OK) {
        first_ret = ret;
    }

    ret = GPIO_Driver_CAM_PWR->Uninitialize(BOARD_CAMERA_POWER_GPIO_PIN);
    return (first_ret == ARM_DRIVER_OK) ? ret : first_ret;
}

